PROCEDURE @@proc@@ (p_run IN NUMBER) IS
    l_seen PLS_INTEGER := 0;
BEGIN
    -- touch every row of the run, one by one
    FOR rec IN (SELECT id, @@col@@
                  FROM @@tab@@
                 WHERE run_id = p_run) LOOP
        l_seen := l_seen + 1;
        UPDATE /* touch */ @@tab2@@ -- @expect
           SET @@col@@ = rec.@@col@@
         WHERE id = rec.id;
    END LOOP;
    @@proc2@@(l_seen);
END @@proc@@;

PROCEDURE @@proc@@ IS
    CURSOR c_src IS
        SELECT id FROM @@tab@@;
BEGIN
    <<rows>>
    FOR rec IN c_src LOOP
        BEGIN
            DELETE FROM @@tab2@@ -- @expect
             WHERE ref_id = rec.id;
        EXCEPTION
            WHEN VALUE_ERROR THEN
                RAISE;
        END;
    END LOOP rows;
END @@proc@@;

PROCEDURE @@proc@@ (p_flag IN VARCHAR2) IS
    CURSOR c_all IS SELECT id, @@col@@ FROM @@tab@@;
    l_row c_all%ROWTYPE;
BEGIN
    OPEN c_all;
    LOOP
        FETCH c_all INTO l_row;
        EXIT WHEN c_all%NOTFOUND;
        IF p_flag = 'A' THEN
            @@proc2@@(l_row.id);
        ELSIF p_flag = 'B' THEN
            INSERT INTO @@tab2@@ (id) VALUES (l_row.id); -- @expect
        END IF;
    END LOOP;
    CLOSE c_all;
END @@proc@@;

PROCEDURE @@proc@@ IS
BEGIN
    FOR rec IN (SELECT id, qty FROM @@tab@@) LOOP
        FOR n IN 1 .. rec.qty LOOP
            @@proc2@@(rec.id, n);
        END LOOP;
        UPDATE @@tab@@ SET @@col@@ = SYSDATE WHERE id = rec.id; -- @expect
    END LOOP;
END @@proc@@;

PROCEDURE @@proc@@ (p_run IN NUMBER) IS
    PROCEDURE copy_rows (p_r IN NUMBER) IS
    BEGIN
        FOR rec IN (SELECT id FROM @@tab@@ WHERE run_id = p_r) LOOP
            INSERT INTO @@tab2@@ (id) VALUES (rec.id); -- @expect
        END LOOP;
    END copy_rows;
BEGIN
    copy_rows(p_run);
    @@proc2@@(p_run);
END @@proc@@;

