        /* INSERT INTO t VALUES (rec.id); */
    END LOOP;
END @@proc@@;

PROCEDURE @@proc@@ (p_run IN NUMBER) IS
BEGIN
    <<scan>>
    FOR rec IN (SELECT id FROM @@tab@@ WHERE run_id = p_run) LOOP
        @@proc2@@(rec.id);
    END LOOP scan;
    UPDATE @@tab2@@
       SET @@col@@ = SYSDATE
     WHERE run_id = p_run;
    DELETE FROM @@tab@@ WHERE run_id = p_run;
END @@proc@@;

PROCEDURE @@proc@@ (p_n IN PLS_INTEGER) IS
BEGIN
    FOR rec IN (SELECT id FROM @@tab@@) LOOP
        @@proc2@@(rec.id);
    END LOOP;
    FOR i IN REVERSE 1 .. p_n LOOP
        INSERT INTO @@tab2@@ (seq) VALUES (i);
    END LOOP;
    @@proc2@@(p_n);
END @@proc@@;

PROCEDURE @@proc@@ (p_max IN PLS_INTEGER) IS
    l_i PLS_INTEGER := 1;
BEGIN
    WHILE l_i <= p_max LOOP
        UPDATE @@tab@@
           SET @@col@@ = l_i
         WHERE id = l_i;
        l_i := l_i + 1;
    END LOOP;
    LOOP
        l_i := l_i - 1;
        DELETE FROM @@tab2@@ WHERE id = l_i;
        EXIT WHEN l_i <= 0;
    END LOOP;
END @@proc@@;

PROCEDURE @@proc@@ (p_id IN NUMBER) IS
    l_msg VARCHAR2(100);
    l_try PLS_INTEGER := 0;
BEGIN
    LOOP
        -- FETCH c_rows INTO l_row;
        l_msg := 'FETCH c_rows INTO l_row';
        l_try := l_try + 1;
        INSERT INTO @@tab@@ (id, note) VALUES (p_id, l_msg);
        EXIT WHEN l_try >= 3;
    END LOOP;
END @@proc@@;
